-- #225: the wilds' new yields. Copper and tin veins on the ranges' flanks
-- (copper on the even massifs, tin on the odd), reed beds in the lakes'
-- shallows and the slow rivers' margins, and old growth as a resource of its
-- own, where W6 grew the wilds' trees as `tree`.
--
-- The wild resources share one spacing grid and are placed in order, woods
-- first, so new types move every wild node placed after them. This replaces
-- W6's wild rows (20261113_001_wild_nodes.sql) rather than adding to them:
-- every node of W6's types in the Wilderness (r3800 and out) goes, from the
-- seeds not yet planted and from resource_nodes, and the new plan comes in.
-- Nothing in the wilds can be claimed, so no owner loses a node. E2.3's rows,
-- inside r3800, are untouched: the wilds are placed after every other zone.
--
-- The rows come from the ignored test `print_new_nodes`, and
-- `the_migration_writes_the_default_plan` checks they still match the plan.
--
--   old_growth 4064, fallen_branches 2032, rock_outcrop 1355, copper_vein 677,
--   iron_vein 542, reed_bed 406, clay_bank 271, tin_vein 271
--
-- They wait in resource_node_seeds until startup's content sync has made
-- their types (`node_spawn::plant_seeds`, #207). Planting skips any id that's
-- already there.
DELETE FROM resource_node_seeds
WHERE resource_type IN ('tree', 'fallen_branches', 'rock_outcrop', 'iron_vein', 'clay_bank')
  AND sqrt(power(position_x - 6000, 2) + power(position_y - 6000, 2)) >= 3800;

DELETE FROM resource_nodes
WHERE resource_type IN ('tree', 'fallen_branches', 'rock_outcrop', 'iron_vein', 'clay_bank')
  AND sqrt(power(position_x - 6000, 2) + power(position_y - 6000, 2)) >= 3800;

